class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD&&window.SW_GEO_SP?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, SUB=CF.sub.SP, CT=CF.country, $=id=>document.getElementById(id), G=SW_GEO_SP, MU=SWD.munis();
    const m=SWD.q.get('m')&&G.meta[SWD.q.get('m')]?SWD.q.get('m'):SUB.ficha, nm=SWD.name(m);
    SWD.page({active:'ficha',lv:'SUB',place:nm,title:nm,sub:`${SUB.regionLabel} de ${G.meta[m][1]} · ${SUB.name}`});
    const rk=(obj)=>{const v=MU.filter(k=>obj[k]!=null).sort((a,b)=>obj[b]-obj[a]); return v.indexOf(m)+1};
    const cell=(l,v,stamp)=>`<div><div class="lbl">${l}</div><b>${v}</b>${stamp}</div>`;
    $('top').innerHTML=cell('População no Censo 2022',SWD.int(D.pop[m]),`<div class="stamp">${SWD.freq('censo')}<span>${rk(D.pop)}º de ${MU.length} no estado</span></div>`)
      +cell(`Estimativa ${D.estYear}`,SWD.int(D.est[m]),SWD.stamp('est'))
      +cell('Crescimento 2010–2022',SWD.sgn(D.tx[m],2,'% ao ano'),SWD.stamp('pop'))
      +cell('Densidade',SWD.num(D.dens[m],1)+' hab/km²',SWD.stamp('dens'));
    const cmp3=(f,fmt)=>{ const L=[[nm,m,true],[SUB.name,'SP'],[CT.name,'BR']], vals=L.map(x=>f(x[1])), mx=Math.max(...vals.map(v=>Math.abs(v||0)),1e-9);
      return `<div class="cmp3">${L.map(([n,k,me],i)=>`<div class="${me?'me':''}"><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${n}</span><span class="bar">${vals[i]==null?'':`<i style="width:${Math.abs(vals[i])/mx*100}%"></i>`}</span><b>${vals[i]==null?'—':fmt(vals[i])}</b></div>`).join('')}</div>`; };
    const card=(h,body,stamp,extra='')=>`<section class="card" ${extra}><h3>${h}</h3>${body}<div style="margin-top:10px">${stamp}</div></section>`;
    const P=D.pyr[m], s=SWD.ageStats(P), sp=SWD.ageStats(D.pyr.SP);
    const rc=D.raca[m], rt=rc.reduce((a,b)=>a+(b||0),0), R=CF.RACA;
    const urb=k=>D.sit[k][0]/(D.sit[k][0]+D.sit[k][1])*100;
    const nb=D.nascM[m], ob=D.obitM[m], ind=D.ind[m], qui=D.qui[m];
    const grp=(n,v,terr)=>v[0]==null?`<div class="fact"><span>${n}</span><b>${SWD.nodata()}</b></div>`:`<div class="fact"><span>${n}</span><b>${SWD.int(v[0])} · ${SWD.pct(v[1],2)}</b></div>${v[2]?`<div class="fact"><span>${terr}</span><b>${SWD.int(v[2])}</b></div>`:''}`;
    $('fx').innerHTML=
      card('Idade e sexo',`<div id="pyr" style="margin-top:6px"></div><div class="lgx" style="margin:6px 0 10px"><span><i style="background:var(--sx-m)"></i>Homens</span><span><i style="background:var(--sx-f)"></i>Mulheres</span><span><i class="ln"></i>${SUB.name}</span></div>
        <div class="fact" style="display:flex;justify-content:space-between;font-size:14px;color:var(--sub)"><span>Idade mediana</span><b style="color:var(--ink)">${SWD.num(s.med,1)} anos</b></div>${cmp3(k=>D.envel[k],v=>SWD.num(v,0))}<div style="font-size:13px;color:var(--faint)">Pessoas de 65 anos ou mais para cada 100 de 0 a 14</div>`,SWD.stamp('pyr'),'style="grid-row:span 2"')
      +card('Crescimento ao ano, 2010–2022',`<div class="big2">${SWD.sgn(D.tx[m],2)}%</div>${cmp3(k=>D.tx[k],v=>SWD.sgn(v,2,'%'))}`,SWD.stamp('pop'))
      +card('Cor ou raça',`<div class="stack" style="height:16px;margin-top:10px" role="img" aria-label="${R.map((r,i)=>`${r.n} ${SWD.num(rc[i]/rt*100,1)}%`).join(', ')}">${R.map((r,i)=>`<i style="width:${rc[i]/rt*100}%;background:var(--c${i+1})"></i>`).join('')}</div>
        <div class="facts" style="border:0;padding-top:4px">${R.map((r,i)=>`<div class="fact"><span style="display:flex;gap:8px;align-items:center"><i style="width:12px;height:12px;border-radius:3px;background:var(--c${i+1})"></i>${r.n}</span><b>${SWD.pct(rc[i]/rt*100,1)}</b></div>`).join('')}</div><div style="font-size:13px;color:var(--faint)">Termos do IBGE. As cores só distinguem as categorias.</div>`,SWD.stamp('raca'))
      +card('Domicílios',`<div class="big2">${SWD.int(D.dom[m][0])}</div><div style="font-size:14px;color:var(--sub)">domicílios particulares ocupados</div><div style="font-size:14px;color:var(--sub);margin-top:10px">Pessoas por domicílio</div>${cmp3(k=>D.dom[k][1],v=>SWD.num(v,2))}<div class="fact" style="display:flex;justify-content:space-between;font-size:14px;color:var(--sub);margin-top:8px"><span>Moram em área urbana</span><b style="color:var(--ink)">${SWD.pct(urb(m),1)}</b></div>`,SWD.stamp('dom'))
      +card('Nascimentos e mortes, 2024',`<div class="facts" style="border:0;padding-top:0;margin-top:6px"><div class="fact"><span>Nascimentos</span><b>${nb==null?'sem dado':SWD.int(nb)}</b></div><div class="fact"><span>Mortes</span><b>${ob==null?'sem dado':SWD.int(ob)}</b></div><div class="fact"><span>Nascimentos para cada morte</span><b>${nb&&ob?SWD.num(nb/ob,2):'sem dado'}</b></div></div>`,SWD.stamp('rc'))
      +card('Indígenas e quilombolas',`<div class="facts" style="border:0;padding-top:0;margin-top:6px">${grp('Pessoas indígenas',ind,'Em terras indígenas')}${grp('Pessoas quilombolas',qui,'Em territórios quilombolas')}</div>`,`<div style="display:grid;gap:4px">${SWD.stamp('ind')}${SWD.stamp('qui')}</div>`)
      +card('Esperança de vida',`<div style="margin-top:8px">${SWD.lvbox('estado',`O IBGE calcula por estado. Em ${SUB.name}: ${SWD.num(D.ts.e0.SP[2022],1)} anos em 2022 (projeção).`)}</div>`,SWD.stamp('e0'))
      +card('Migração',`<div style="margin-top:8px">${SWD.lvbox('breve',`De onde vieram os moradores de ${nm}. O Censo 2022 tem o dado por município; a tela por município entra numa próxima etapa.`)}</div>`,'');
    SWD.pyramid($('pyr'),{a:P,cmp:D.pyr.SP,cmpLabel:SUB.name,W:420,H:380,max:5,aria:`Pirâmide etária de ${nm}, 2022`});
    $('src').innerHTML=SWD.srcLine(['pop','est','pyr','raca','dom','rc','ind','qui']);
  }
  renderVals(){ return {}; }
}
